// .rdata string constants that carried pointer tables point AT rather than into. A .rdata
// address is not a bound region, so arithmetic cannot retarget it -- the host needs the
// CONTENT, and these are the REAL bytes, read out of the frozen EN image at generation time.
struct rdata_constant {
    uint32_t       va;    // the original-image address the carried pointer holds
    const wchar_t *text;  // the bytes that lived there, verbatim
    const char    *why;
};

inline constexpr rdata_constant RDATA_CONSTANTS[] = {
    {0x0050108fu,
     L"",
     "G_TEXT_PTRS' shared EMPTY-STRING default -- 86 of the 806 entries hold this address instead of an offset into G_TEXT_BLOCK. NOT llm_strat_empty_name_str, which is a different constant at 0x0050109D (char[1] \"\"); this one is the WIDE empty string the text pool leaves in unassigned slots."},
    // raw bytes at 0050108F, incl. terminator: 0000   (an EMPTY wide string)
};
inline constexpr int RDATA_CONSTANT_COUNT =
    (int)(sizeof(RDATA_CONSTANTS) / sizeof(RDATA_CONSTANTS[0]));

